<script setup lang="ts">
import {ref,onMounted,onBeforeUnmount,watch} from 'vue';import L from 'leaflet';import 'leaflet/dist/leaflet.css';import type {Report} from '../types';const props=defineProps<{reports:Report[];needs:number[]}>();const el=ref<HTMLElement>();const failed=ref(false);let map:L.Map;let layer:L.LayerGroup;function markers(){if(!layer)return;layer.clearLayers();props.reports.forEach((r,i)=>{const content=document.createElement('div');content.textContent=`${r.barangay} · ${r.population.toLocaleString()} people · ${props.needs[i]?.toLocaleString()} L unmet · ${r.urgency?'Elevated urgency':'Standard urgency'} · See delivery operations for assignments`;L.circleMarker([r.lat,r.lng],{radius:11,color:'white',weight:3,fillColor:r.urgency?'#e58a42':'#07878b',fillOpacity:1}).bindPopup(content).addTo(layer)})}onMounted(()=>{map=L.map(el.value!).setView([13.39,121.18],11);L.tileLayer('https://{s}.tile.openstreetmap.org/{z}/{x}/{y}.png',{attribution:'© OpenStreetMap contributors',maxZoom:18}).on('tileerror',()=>failed.value=true).addTo(map);layer=L.layerGroup().addTo(map);markers();});watch(()=>props.reports,markers,{deep:true});onBeforeUnmount(()=>map?.remove());
</script><template><div class="map-wrap"><div ref="el" class="map"></div><span class="map-tag">CALAPAN CITY · SIMULATED SHORTAGES</span></div><p v-if="failed" class="muted">Map tiles unavailable. Community coordinates and shortage details remain available in the list below.</p></template>
